"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[888],{74003:e=>{e.exports=JSON.parse('{"functions":[{"name":"start","desc":"Bootstrap hook. Opens the one red subscription the controller owns:\\n`UI_NOTIFICATION` is re-fired on `ShowNotification`.\\n\\nCalled by `Bootstrap.startControllers` during `Entry.client.luau` step 4 \u2014\\nafter the data gate, so the profile is already in [ClientState] by the time\\nany notification can arrive.","params":[],"returns":[],"function_type":"static","source":{"line":80,"path":"src/Client/Features/Core/Controllers/MessageController.luau"}}],"properties":[],"types":[],"name":"MessageController","desc":"The Signal hub every \\"say something to the player\\" path runs through.\\n\\nIt exists to decouple plain-Lua callers from React. A controller, a prop\\nclass, or an FTUE step cannot render a component, and the React portals\\ncannot be required from arbitrary Lua without dragging the reconciler in.\\nSo both sides meet on a Signal: producers `:Fire()`, the portal component\\n`:Connect()`s in an effect, and neither knows about the other.\\n\\n### Signals\\n\\n* `ShowNotification` \u2014 fired by the `UI_NOTIFICATION` red subscription\\n  opened in [MessageController.start]. This is the only signal the\\n  controller itself produces.\\n* `ShowToast` `Signal<UITypes.ToastData>` \u2014 consumed by `ToasterPortal`,\\n  which also listens for the `UI_TOAST` red action.\\n* `ShowHint` `Signal<UITypes.HintData>` and `ShowMessage`\\n  `Signal<UITypes.MessageData>` \u2014 both consumed by `MessageOverlay`,\\n  which also listens for `UI_HINT` and `UI_MESSAGE`.\\n* `ShowDialog` `Signal<UITypes.DialogData>` / `HideDialog` \u2014 consumed by\\n  `DialogPortal`, which also listens for the `UI_DIALOG` red action.\\n* `PressedOption` `Signal<string>` \u2014 the return leg. `DialogPortal` is the\\n  only producer; callers that need the player\'s choice `:Wait()` on it.\\n\\n### Consumers\\n\\nExactly three files subscribe to these signals, one per portal:\\n\\n* `src/Client/Features/Core/Components/Dialog/DialogPortal.luau`\\n  (`ShowDialog`, `HideDialog`; fires `PressedOption`)\\n* `src/Client/Features/Core/Components/Toaster/ToasterPortal.luau`\\n  (`ShowToast`)\\n* `src/Client/Features/Core/Components/MessageOverlay.luau`\\n  (`ShowMessage`, `ShowHint`)\\n\\nProducers are spread wider: [MonetizationController] (`ShowDialog`),\\n`Market/Controllers/Components/{PurchaseShop,SkinPreviewPane}`\\n(`ShowToast`), `Shared/Class/Base/Props/PropBaseClass` (`ShowToast`) and\\n`Shared/Data/FTUE/FTUEData` (`ShowDialog`).\\n\\nNote `ShowNotification` currently has no consumer \u2014 the `UI_NOTIFICATION`\\naction is subscribed and re-fired, but nothing listens on the far side.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":50,"path":"src/Client/Features/Core/Controllers/MessageController.luau"}}')}}]);